SELECT "line_id", "request_number", "item", "quantity", "way", "customer", "obligation_id", "due", "obligation_state", "qty_ok", "qty_bad", "last_received", "days_open", "reminders", "route", 'incomplete or damaged return' AS "verdict_reason"
FROM (SELECT "t13"."line_id", "t13"."request_number", "t13"."item", "t13"."quantity", "t13"."way", "t13"."customer", "t13"."obligation_id", "t13"."due", "t13"."obligation_state", "t13"."qty_ok", "t13"."qty_bad", "t13"."last_received", "t13"."days_open", "t15"."reminders", CASE WHEN "t13"."qty_ok" >= "t13"."quantity" THEN 'complete' WHEN "t13"."qty_bad" > 0 OR "t13"."qty_ok" > 0 AND "t13"."qty_ok" < "t13"."quantity" THEN 'damaged' WHEN "t13"."days_open" > :inbound_close THEN 'expired' WHEN "t13"."days_open" > :inbound_reminder AND "t15"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
        FROM (SELECT "t4"."line_id", "t4"."request_number", "t4"."item", "t4"."quantity", "t4"."way", "t4"."customer", "t4"."obligation_id", "t4"."due", "t4"."obligation_state", "t4"."qty_ok", "t4"."qty_bad", "t4"."last_received", "t12"."days_open"
                FROM (SELECT "t"."line_id", "t"."request_number", "t"."item", "t"."quantity", "t"."way", "t"."customer", "t"."obligation_id", "t"."due", "t"."obligation_state", "t3"."qty_ok", "t3"."qty_bad", "t3"."last_received"
                        FROM (SELECT "p_ff40000e"."line_id", "p_ff40000e"."request_number", "p_ff40000e"."item", "p_ff40000e"."quantity", "p_ff40000e"."way", "p_ff40000e"."customer0" AS "customer", "p_7d39f2a5"."id" AS "obligation_id", "p_7d39f2a5"."due", "p_7d39f2a5"."state" AS "obligation_state"
                                FROM "p_ff40000e"
                                    INNER JOIN "p_7d39f2a5" ON "p_7d39f2a5"."entity" = 'return_request_line' AND "p_7d39f2a5"."key" = CAST("p_ff40000e"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a5"."kind" = 'inbound' AND "p_7d39f2a5"."state" IN ('open', 'overdue', 'reopened')) AS "t"
                            LEFT JOIN (SELECT "t0"."line_id", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" = 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" <> 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("p_3fc03684"."received_date") AS "last_received"
                                FROM (SELECT "p_ff40000e0"."line_id", "p_ff40000e0"."request_number", "p_ff40000e0"."item", "p_ff40000e0"."quantity", "p_ff40000e0"."way", "p_ff40000e0"."customer0" AS "customer", "p_7d39f2a50"."id" AS "obligation_id", "p_7d39f2a50"."due", "p_7d39f2a50"."state" AS "obligation_state"
                                        FROM "p_ff40000e" AS "p_ff40000e0"
                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a50" ON "p_7d39f2a50"."entity" = 'return_request_line' AND "p_7d39f2a50"."key" = CAST("p_ff40000e0"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a50"."kind" = 'inbound' AND "p_7d39f2a50"."state" IN ('open', 'overdue', 'reopened')) AS "t0"
                                    LEFT JOIN "p_3fc03684" ON "t0"."line_id" = "p_3fc03684"."line_id"
                                GROUP BY "t0"."line_id") AS "t3" ON "t"."line_id" = "t3"."line_id") AS "t4"
                    LEFT JOIN (SELECT "t6"."line_id", CASE WHEN "t6"."_ttrp_a_n15_0" IS NULL THEN NULL ELSE COALESCE("t11"."_ttrp_n_n15_0", 0) END AS "days_open"
                        FROM (SELECT "t5"."line_id", "t5"."request_number", "t5"."item", "t5"."quantity", "t5"."way", "t5"."customer", "t5"."obligation_id", "t5"."due", "t5"."obligation_state", "p_f7cce9af"."recipe", "p_f7cce9af"."run", "p_f7cce9af"."entity", "p_f7cce9af"."key", "p_f7cce9af"."kind", "p_f7cce9af"."due" AS "due0", "p_f7cce9af"."state", "p_f7cce9af"."fulfilled_by", "p_f7cce9af"."fulfilled_at", "p_f7cce9af"."created_at", "p_f7cce9af"."created_at" AS "_ttrp_a_n15_0"
                                FROM (SELECT "p_ff40000e1"."line_id", "p_ff40000e1"."request_number", "p_ff40000e1"."item", "p_ff40000e1"."quantity", "p_ff40000e1"."way", "p_ff40000e1"."customer0" AS "customer", "p_7d39f2a51"."id" AS "obligation_id", "p_7d39f2a51"."due", "p_7d39f2a51"."state" AS "obligation_state"
                                        FROM "p_ff40000e" AS "p_ff40000e1"
                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a51" ON "p_7d39f2a51"."entity" = 'return_request_line' AND "p_7d39f2a51"."key" = CAST("p_ff40000e1"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a51"."kind" = 'inbound' AND "p_7d39f2a51"."state" IN ('open', 'overdue', 'reopened')) AS "t5"
                                    INNER JOIN "p_f7cce9af" ON "t5"."obligation_id" = "p_f7cce9af"."id") AS "t6"
                            LEFT JOIN (SELECT "t9"."_ttrp_a_n15_0" AS "_ttrp_k_n15_0__ttrp_a_n15_0", COUNT("p_58e569ee"."_ttrp_d_n15_0") AS "_ttrp_n_n15_0"
                                FROM (SELECT "p_f7cce9af0"."created_at" AS "_ttrp_a_n15_0"
                                        FROM (SELECT "p_ff40000e2"."line_id", "p_ff40000e2"."request_number", "p_ff40000e2"."item", "p_ff40000e2"."quantity", "p_ff40000e2"."way", "p_ff40000e2"."customer0" AS "customer", "p_7d39f2a52"."id" AS "obligation_id", "p_7d39f2a52"."due", "p_7d39f2a52"."state" AS "obligation_state"
                                                FROM "p_ff40000e" AS "p_ff40000e2"
                                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a52" ON "p_7d39f2a52"."entity" = 'return_request_line' AND "p_7d39f2a52"."key" = CAST("p_ff40000e2"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a52"."kind" = 'inbound' AND "p_7d39f2a52"."state" IN ('open', 'overdue', 'reopened')) AS "t7"
                                            INNER JOIN "p_f7cce9af" AS "p_f7cce9af0" ON "t7"."obligation_id" = "p_f7cce9af0"."id"
                                        GROUP BY "p_f7cce9af0"."created_at") AS "t9"
                                    INNER JOIN "p_58e569ee" ON "t9"."_ttrp_a_n15_0" < "p_58e569ee"."_ttrp_d_n15_0" AND "p_58e569ee"."_ttrp_d_n15_0" <= :as_of
                                GROUP BY "t9"."_ttrp_a_n15_0") AS "t11" ON "t6"."_ttrp_a_n15_0" = "t11"."_ttrp_k_n15_0__ttrp_a_n15_0") AS "t12" ON "t4"."line_id" = "t12"."line_id") AS "t13"
            LEFT JOIN (SELECT "t14"."line_id", COUNT("p_4fd248ed"."run") AS "reminders"
                FROM (SELECT "p_ff40000e3"."line_id", "p_ff40000e3"."request_number", "p_ff40000e3"."item", "p_ff40000e3"."quantity", "p_ff40000e3"."way", "p_ff40000e3"."customer0" AS "customer", "p_7d39f2a53"."id" AS "obligation_id", "p_7d39f2a53"."due", "p_7d39f2a53"."state" AS "obligation_state"
                        FROM "p_ff40000e" AS "p_ff40000e3"
                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a53" ON "p_7d39f2a53"."entity" = 'return_request_line' AND "p_7d39f2a53"."key" = CAST("p_ff40000e3"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a53"."kind" = 'inbound' AND "p_7d39f2a53"."state" IN ('open', 'overdue', 'reopened')) AS "t14"
                    LEFT JOIN "p_4fd248ed" ON "t14"."line_id" = "p_4fd248ed"."line_id" AND "p_4fd248ed"."route" = 'remind'
                GROUP BY "t14"."line_id") AS "t15" ON "t13"."line_id" = "t15"."line_id") AS "t16"
WHERE "t16"."route" = 'damaged'
